from dataclasses import dataclass, field

import requests
import structlog

log = structlog.get_logger()

LEDGER_URL = "https://ledger.internal.acme.example/v1/postings"


@dataclass
class Invoice:
    id: str
    customer_id: str
    subtotal_cents: int
    tax_cents: int = 0
    ledger_ref: str | None = None
    lines: list = field(default_factory=list)


LEDGER_MAX_ATTEMPTS = 3


def _post_to_ledger(invoice):
    # Safe to retry: the ledger deduplicates postings on invoice id.
    for attempt in range(1, LEDGER_MAX_ATTEMPTS + 1):
        try:
            resp = requests.post(LEDGER_URL, json={"invoice": invoice.id, "amount": invoice.subtotal_cents + invoice.tax_cents}, timeout=10)
            if resp.status_code < 500:
                resp.raise_for_status()
                return resp
            resp.raise_for_status()
        except (requests.ConnectionError, requests.Timeout, requests.HTTPError) as exc:
            if isinstance(exc, requests.HTTPError) and exc.response is not None and exc.response.status_code < 500:
                raise
            if attempt == LEDGER_MAX_ATTEMPTS:
                raise
            log.warning("ledger_post_retry", invoice_id=invoice.id, attempt=attempt, error=str(exc))


def finalize(invoice):
    resp = _post_to_ledger(invoice)
    invoice.ledger_ref = resp.json()["ref"]
    log.info("invoice_finalized", invoice_id=invoice.id)
    return invoice


def finalize_once(invoice):
    if invoice.ledger_ref:
        return invoice
    return finalize(invoice)
